package live.linghe.privateinput;

import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.math.*;import java.util.*;import org.json.*;

/** Exact wire integers and manual import/sync separation in a fresh synthetic directory. */
public final class CliData10Check {
 private static final String A="AAAAAAAA-AAAA-AAAA-AAAA-AAAAAAAAAAAA",B="BBBBBBBB-BBBB-BBBB-BBBB-BBBBBBBBBBBB",C="CCCCCCCC-CCCC-CCCC-CCCC-CCCCCCCCCCCC";
 private static int checks;private static File base;
 interface Work{void run()throws Exception;}
 private static void require(boolean value,String label){if(!value)throw new AssertionError(label);}
 private static void reject(Work work,String label)throws Exception{boolean rejected=false;try{work.run();}catch(Exception expected){rejected=true;}require(rejected,label);}
 private static PersonalLexicon store(String name){return new PersonalLexicon(new File(base,name));}
 private static String text(Path path)throws Exception{return new String(Files.readAllBytes(path),StandardCharsets.UTF_8);}
 private static void write(File file,String text)throws Exception{Files.write(file.toPath(),text.getBytes(StandardCharsets.UTF_8));}
 private static PersonalLexicon.Entry entry(String id,String text,String trigger){return new PersonalLexicon.Entry(id,"phrase",text,trigger);}
 private static String archive(String sequence,boolean deleted,String device)throws Exception {
  JSONObject item=entry(A,"跨端合成条目","cs").json();JSONObject record=new JSONObject().put("entry",item).put("deleted",deleted).put("revision",new JSONObject().put("sequence","REVISION_TOKEN").put("device",device)).put("created",new JSONObject().put("sequence",1).put("device",device));
  return new JSONObject().put("version",1).put("entries",deleted?new JSONArray():new JSONArray().put(item)).put("synchronization",new JSONObject().put("version",1).put("records",new JSONObject().put(A,record))).toString().replace("\"REVISION_TOKEN\"",sequence);
 }
 private static BigInteger revision(PersonalLexicon.Snapshot state,String id)throws Exception{return LosslessJson.unsigned(LosslessJson.object(state.encode(),PersonalLexicon.MAX_BYTES).getJSONObject("synchronization").getJSONObject("records").getJSONObject(id).getJSONObject("revision").get("sequence"));}
 public static void main(String[] args){try{run(args);}catch(Throwable error){error.printStackTrace();System.exit(1);}}
 private static void run(String[] args)throws Exception {
  base=new File(args[0]);require(!base.exists()&&base.mkdirs(),"fresh fixture only");File exported=new File(args[2]);require(exported.mkdirs(),"fresh result directory");
  int vectors=0,decimalDifferences=0;
  for(String line:Files.readAllLines(Paths.get(args[1]),StandardCharsets.UTF_8)) {
   String[] row=line.split("\t",-1);String json=new String(Base64.getDecoder().decode(row[3]),StandardCharsets.UTF_8);
   PersonalLexicon.Snapshot decoded=null;try{decoded=PersonalLexicon.decode(json);}catch(Exception invalid){}
   require((decoded==null)==row[2].equals("invalid"),"exact numeric acceptance vector "+row[0]);
   if(decoded!=null)require(revision(decoded,A).equals(new BigInteger(row[2])),"no precision loss vector "+row[0]);if(!row[1].equals(row[2]))decimalDifferences++;vectors++;
  }
  require(vectors>15,"Swift vectors loaded");checks++;
  PersonalLexicon high=store("high");high.merge(archive("9223372036854775809",false,B));high.upsert(entry(A,"精确跨端修订","cs"),null);require(revision(high.load(),A).equals(new BigInteger("9223372036854775810")),"increment above signed max exactly");write(new File(exported,"high-edited.json"),high.load().encode());checks++;
  PersonalLexicon maximum=store("maximum");maximum.merge(archive("18446744073709551614",false,B));maximum.upsert(entry(A,"边界合成更新","cs"),null);require(revision(maximum.load(),A).equals(LosslessJson.UINT64_MAX),"last UInt64 increment");String immutable=maximum.load().encode();reject(()->maximum.remove(A),"maximum overflow rejected");require(maximum.load().encode().equals(immutable),"overflow leaves existing archive intact");write(new File(exported,"max-edited.json"),maximum.load().encode());checks++;
  PersonalLexicon left=store("delete-left"),right=store("delete-right");String live=archive("9223372036854775811",false,C),deleted=archive("9223372036854775811",true,B);left.merge(live);left.merge(deleted);right.merge(deleted);right.merge(live);require(left.load().entries.isEmpty()&&right.load().entries.isEmpty(),"concurrent UInt64 delete wins both orders");checks++;
  PersonalLexicon manual=store("manual");manual.upsert(entry(A,"本地保留","cs"),null);
  JSONObject payload=new JSONObject().put("version",1).put("entries",new JSONArray().put(entry(A,"远端冲突","cs").json()).put(entry(B,"新增合成","xz").json()));
  manual.importEntries(payload.toString(),null);require(manual.load().entries.size()==2&&manual.load().entries.get(0).text.equals("本地保留"),"manual import local UUID wins and appends missing entry");checks++;
  String before=manual.load().encode();manual.importEntries(archive("18446744073709551615",true,B),null);require(manual.load().encode().equals(before),"manual file never applies remote tombstones or version counters");manual.upsert(entry(C,"仅用于已移除测试","yc"),null);manual.remove(C);String visible=manual.exportEntries();JSONObject publicCopy=LosslessJson.object(visible,PersonalLexicon.MAX_BYTES);require(!publicCopy.has("synchronization")&&publicCopy.getJSONArray("entries").length()==2&&!visible.contains("仅用于已移除测试")&&!visible.contains("personal-replica"),"export only active user entries, no deleted data or replica metadata");write(new File(exported,"visible-export.json"),visible);checks++;
  File manualFile=new File(base,"manual/personal-lexicon-v1.json");long stamp=1700000000000L;Files.setLastModifiedTime(manualFile.toPath(),java.nio.file.attribute.FileTime.fromMillis(stamp));manual.importEntries(visible,null);require(manualFile.lastModified()==stamp,"unchanged imports do not rewrite storage");checks++;
  JSONObject bad=new JSONObject().put("version",1).put("entries",new JSONArray().put(entry("DDDDDDDD-DDDD-DDDD-DDDD-DDDDDDDDDDDD","有效新短语","yx").json()).put(new PersonalLexicon.Entry("EEEEEEEE-EEEE-EEEE-EEEE-EEEEEEEEEEEE","word","无效拼音","notasyllable").json()));
  before=manual.load().encode();reject(()->manual.importEntries(bad.toString(),new HashSet<>(Arrays.asList("ni","hao"))),"invalid syllable aborts whole import");require(manual.load().encode().equals(before),"mixed import is atomic");checks++;
  reject(()->PersonalLexicon.decode(archive("1",false,B).replace("\"sequence\":1,","\"sequence\":1,\"sequence\":2,")),"duplicate keys rejected");reject(()->LosslessJson.object("{\"x\":\\\"broken\\\"}",512),"malformed JSON rejected");
  String deep="0";for(int i=0;i<30;i++)deep="["+deep+"]";final String tooDeep="{\"extra\":"+deep+"}";reject(()->LosslessJson.object(tooDeep,4096),"depth bounded");reject(()->LosslessJson.unsigned(new BigDecimal("1e1000000")),"huge numeric expansion rejected before allocation");reject(()->LosslessJson.unsigned(new BigDecimal("1e-1000000")),"fractional expansion rejected before allocation");checks++;
  PersonalLexicon sync=store("sync-only");String envelope=high.synchronizationSnapshot();sync.mergeSynchronized(envelope);require(sync.load().entries.get(0).text.equals("精确跨端修订")&&revision(sync.load(),A).equals(new BigInteger("9223372036854775810")),"wire sync-only envelope accepted without visible entries wrapper");sync.remove(A);high.mergeSynchronized(sync.synchronizationSnapshot());require(high.load().entries.isEmpty(),"sync-only deletion converges");checks++;
  PersonalLexicon legacy=store("legacy");File legacyDir=new File(base,"legacy");require(legacyDir.mkdirs(),"legacy fixture directory");write(new File(legacyDir,"personal-lexicon-v1.json"),visible);String migrated=legacy.synchronizationSnapshot();JSONObject records=LosslessJson.object(migrated,PersonalLexicon.MAX_BYTES).getJSONObject("records");String replica=text(new File(legacyDir,"personal-replica-id.txt").toPath());require(records.getJSONObject(A).getJSONObject("revision").getString("device").equals(replica)&&legacy.load().entries.size()==2,"legacy seeds with persisted local replica");checks++;
  PersonalLexicon capacity=store("capacity");capacity.upsert(entry(A,"原有合成","yy"),null);JSONArray many=new JSONArray();for(int i=0;i<1000;i++){String id=String.format(Locale.ROOT,"%08x-0000-0000-0000-000000000000",i+1);many.put(entry(id,"合成容量"+i,"cr").json());}String packed=new JSONObject().put("version",1).put("entries",many).toString(),original=capacity.load().encode();reject(()->capacity.importEntries(packed,null),"union capacity rejected before write");require(capacity.load().encode().equals(original),"capacity failure retains all prior entries");checks++;
  PersonalLexicon unicode=store("unicode");unicode.upsert(entry(A,"e\u0301","ee"),null);reject(()->unicode.upsert(entry(B,"é","ee"),null),"canonical equivalent visible duplicates rejected");require(unicode.load().entries.get(0).text.equals("e\u0301"),"text remains in original Unicode representation");checks++;
  PersonalLexicon oldAliases=store("old-aliases");File aliasDirectory=new File(base,"old-aliases");require(aliasDirectory.mkdirs(),"legacy alias fixture");String legacyAliases=new JSONObject().put("version",1).put("entries",new JSONArray().put(entry(A,"e\u0301","ee").json()).put(entry(B,"é","ee").json())).toString();File aliasFile=new File(aliasDirectory,"personal-lexicon-v1.json");write(aliasFile,legacyAliases);require(oldAliases.load().entries.size()==1&&text(aliasFile.toPath()).equals(legacyAliases),"old local aliases display once without rewriting original file");String aliases=oldAliases.synchronizationSnapshot();require(LosslessJson.object(aliases,PersonalLexicon.MAX_BYTES).getJSONObject("records").length()==2,"legacy migration retains every alias UUID");oldAliases.remove(A);oldAliases.mergeSynchronized(aliases);require(oldAliases.load().entries.isEmpty(),"canonical aliases retire together and cannot resurrect");reject(()->PersonalLexicon.decode(legacyAliases),"external duplicate import still rejected");checks++;
  String document="{\"version\":1,\"entries\":[]}";require(LexiconDocuments.read(new ByteArrayInputStream(document.getBytes(StandardCharsets.UTF_8))).equals(document),"native document stream boundary");
  reject(()->LexiconDocuments.read(new ByteArrayInputStream(new byte[]{(byte)0xc3,0x28})),"invalid UTF8 document rejected");reject(()->LexiconDocuments.read(new ByteArrayInputStream(new byte[PersonalLexicon.MAX_BYTES+1])),"provider length cannot bypass byte cap");
  ByteArrayOutputStream output=new ByteArrayOutputStream();LexiconDocuments.write(output,visible);require(new String(output.toByteArray(),StandardCharsets.UTF_8).equals(visible),"document export is exactly visible JSON");checks++;
  System.out.println("Passed "+checks+" exact UInt64/import/export/sync-contract checks and "+vectors+" numeric vectors ("+decimalDifferences+" documented noncanonical decimal differences from Swift); installed app/UI/network untouched");
 }
}
